def solve_recursive(N, max_val):
    a = [-1] * (N + 1)
    solutions = []

    def check_p(p):
        # Check if the condition a[a[a[p]]] = a[p+1] + 1 can be verified
        # We need a[p], a[a[p]], a[a[a[p]]], and a[p+1] to be known.
        try:
            # This is not quite right because a[p] might be > N.
            # But we are limiting max_val.
            val_p = a[p]
            if val_p == -1 or val_p > N: return True # Cannot verify yet
            val_ap = a[val_p]
            if val_ap == -1 or val_ap > N: return True # Cannot verify yet
            val_aap = a[val_ap]
            if val_aap == -1 or val_aap > N: return True # Cannot verify yet
            val_p_plus_1 = a[p+1]
            if val_p_plus_1 == -1: return True # Cannot verify yet

            return val_aap == val_p_plus_1 + 1
        except IndexError:
            return True

    def backtrack(idx):
        if idx == N + 1:
            # Final check for all p in 0...N-1
            for p in range(N):
                if not check_p(p): return
            solutions.append(tuple(a))
            return

        for v in range(max_val + 1):
            a[idx] = v
            # Prune: check all p such that all required indices are <= idx
            possible = True
            for p in range(idx):
                # we need a[p], a[a[p]], a[a[a[p]]], and a[p+1]
                # All these must be <= idx to be checkable
                # But the condition is a[a[a[p]]] = a[p+1] + 1.
                # If p+1 <= idx and a[p] <= idx and a[a[p]] <= idx and a[a[a[p]]] <= idx, we check it.
                if p+1 <= idx:
                    try:
                        if a[p] != -1 and a[p] <= idx:
                            if a[a[p]] != -1 and a[a[p]] <= idx:
                                if a[a[a[p]]] != -1 and a[a[a[p]]] <= idx:
                                    if a[a[a[p]]] != a[p+1] + 1:
                                        possible = False
                                        break
                    except IndexError:
                        pass
            if possible:
                backtrack(idx + 1)
            a[idx] = -1

    backtrack(0)
    return solutions

