    solutions = []

    def backtrack(idx):
        if idx == N + 1:
            # Check for p = 0...N-1
            for p in range(N):
                try:
                    if a[a[a[p]]] != a[p+1] + 1:
                        return
                except IndexError:
                    return
            solutions.append(tuple(a[:N+1]))
            return

        for v in range(max_val + 1):
            a[idx] = v
            # Simple pruning
            possible = True
            for p in range(idx):
                if p+1 <= idx:
                    try:
                        if a[p] != -1 and a[p] <= idx:
                            if a[a[p]] != -1 and a[a[p]] <= idx:
                                if a[a[a[p]]] != -1 and a[a[a[p]]] <= idx:
                                    if a[a[a[p]]] != a[p+1] + 1:
                                        possible = False
                                        break
                    except IndexError:
                        pass
            if possible:
                backtrack(idx + 1)
            a[idx] = -1

    backtrack(0)
    return solutions

