def solve_small_all(N, max_val):
    import itertools
    solutions = []
    for a in itertools.product(range(max_val + 1), repeat=N+1):
        possible = True
        for p in range(N):
            try:
                # Must have a[p], a[a[p]], a[a[a[p]]], a[p+1] all within range
                if not (0 <= a[p] <= N and 0 <= a[a[p]] <= N and 0 <= a[a[a[p]]] <= N):
                    possible = False
                    break
                if a[a[a[p]]] != a[p+1] + 1:
                    possible = False
                    break
            except IndexError:
                possible = False
                break
        if possible:
            solutions.append(a)
    return solutions

